def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 97:
        return 'D'

    # Count cooperation rates
    my_coop = 0
    opp_coop = 0
    for (me, opp) in history:
        if me == 'C':
            my_coop += 1
        if opp == 'C':
            opp_coop += 1

    my_rate = my_coop / n
    opp_rate = opp_coop / n

    # Last few moves for recency detection
    last_me = history[-1][0]
    last_opp = history[-1][1]

    # Detect possible defection streak by opponent
    opp_last_defects = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_last_defects += 1
        else:
            break

    my_last_defects = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_last_defects += 1
        else:
            break

    # Early game: establish cooperation
    if n < 3:
        return 'C'

    # If opponent has been mostly cooperative, keep cooperating
    if opp_rate > 0.7:
        # But occasionally test / avoid being exploited
        if opp_last_defects >= 3:
            return 'D'
        return 'C'

    # If opponent has been mostly defecting, defect
    if opp_rate < 0.25:
        # Try occasional cooperation to re-establish
        if n > 10 and opp_last_defects >= 5 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Middle range: tit-for-tat with forgiveness
    if last_opp == 'D':
        # If we've been defecting a while, occasionally forgive
        if my_last_defects >= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_me == 'D' and opp_last_defects == 0:
        # We defected, they cooperated — they may be forgiving, exploit?
        if opp_rate > 0.5:
            return 'C'
        return 'D'

    return 'C'
